def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            r0 = min(rr for rr, cc in cells)
            r1 = max(rr for rr, cc in cells)
            c0 = min(cc for rr, cc in cells)
            c1 = max(cc for rr, cc in cells)
            if r1 - r0 >= 2 and c1 - c0 >= 2:
                objects.append((color, cells, r0, r1, c0, c1))

    sources = []
    for color, cells, r0, r1, c0, c1 in objects:
        if all(grid[r][c] == color for c in range(c0, c1 + 1)
               for r in (r0, r1)) and all(
               grid[r][c] == color for r in range(r0, r1 + 1)
               for c in (c0, c1)):
            motif = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                     for r in range(r0 + 1, r1)]
            if any(any(row) for row in motif):
                sources.append((r1-r0-1, c1-c0-1, motif))

    if not sources:
        return out

    mh, mw, motif = sources[0]
    source_dims = (mh, mw)

