        if not (all(grid[r][c] == color for c in range(c0, c1 + 1)
                    for r in (r0, r1)) and all(
                    grid[r][c] == color for r in range(r0, r1 + 1)
                    for c in (c0, c1))):
            continue

        ih, iw = r1-r0-1, c1-c0-1
        if (ih, iw) != source_dims:
            for r, c in cells:
                out[r][c] = 0
            continue

        for i in range(ih):
            for j in range(iw):
                out[r0 + 1 + i][c0 + 1 + j] = color if motif[i][j] else 0

    return out
